import { useState } from "react";
import { ApiError, api } from "../services/api";
import type { OptimizationRun } from "../types/hexam";
import { Spinner } from "./ui";

/** Downloads the PDF comparison report (official exam times vs this run) generated by the backend. */
export function ReportButton({ run, className = "btn-ghost" }: { run: OptimizationRun; className?: string }) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  if (!run.schedule || !run.result?.after) return null;

  const download = async () => {
    setBusy(true);
    setError(null);
    try {
      const blob = await api.runReport(run.run_id);
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `hexam-report-${run.run_id}.pdf`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (e) {
      setError(e instanceof ApiError ? e.message : "Could not generate the report.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <span className="inline-flex flex-col gap-1">
      <button type="button" className={className} onClick={download} disabled={busy} title="Official vs optimized exam times, with every metric">
        {busy ? <Spinner /> : <PdfIcon />}
        {busy ? "Generating PDF…" : "Download PDF report"}
      </button>
      {error && (
        <span role="alert" className="text-xs text-bad">
          {error}
        </span>
      )}
    </span>
  );
}

function PdfIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z" />
      <path d="M14 3v5h5" />
      <path d="M12 12v6m-3-3 3 3 3-3" />
    </svg>
  );
}
